package com.bank.loan.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "loan_accounts")
public class LoanAccount {
    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;
    @Column(name = "account_type") private String accountType;
    private String status;

    protected LoanAccount() {}

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient pool balance");
        balance = balance.subtract(amount);
    }

    public void credit(BigDecimal amount) {
        if (!"ACTIVE".equals(status)) throw new IllegalStateException("Account " + accountId + " is " + status);
        balance = balance.add(amount);
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public String getStatus() { return status; }
}
