// REQUIRES_NEW: audit log commits EVEN IF the main TX rolls back
package com.bank.loan.service;

import com.bank.loan.model.AuditRecord;
import com.bank.loan.repository.AuditRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class AuditService {

    private final AuditRepository auditRepo;

    /**
     * REQUIRES_NEW: SUSPENDS the calling TX, opens a NEW independent TX.
     *
     * Flow:
     * 1. Outer TX (DisbursementService) is SUSPENDED
     * 2. New connection obtained from HikariCP (holds TWO connections now!)
     * 3. Audit record saved in the new TX
     * 4. New TX COMMITTED (independently — regardless of outer TX outcome)
     * 5. Outer TX RESUMED
     *
     * USE CASE: compliance requires EVERY disbursement attempt to be logged,
     * INCLUDING failed ones. If the main TX rolls back (credit to frozen account),
     * the audit record of the FAILED attempt still exists for regulators.
     *
     * WARNING: holds TWO connections simultaneously per thread!
     * HikariCP sizing: maxPoolSize >= threads × (maxNestedDepth - 1) + 1
     */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logDisbursement(String accountId, BigDecimal amount, String status, String details) {
        AuditRecord record = new AuditRecord("LOAN_DISBURSEMENT", accountId, amount, status, details);
        auditRepo.save(record);
        log.info("[AUDIT-REQUIRES_NEW] {} {} Rs.{} — committed in INDEPENDENT TX",
            status, accountId, amount);
    }
}
