package com.bank.loan.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@Slf4j
public class ComplianceService {

    /**
     * MANDATORY: this method MUST run within an existing TX.
     * If called without a TX → IllegalTransactionStateException.
     * USE CASE: compliance check MUST participate in the main TX.
     * If the main TX rolls back, this check's results are also undone.
     */
    @Transactional(propagation = Propagation.MANDATORY)
    public boolean checkCompliance(String accountId, BigDecimal amount) {
        log.info("[COMPLIANCE-MANDATORY] Checking {} Rs.{} — MUST be within existing TX", accountId, amount);
        if (amount.compareTo(new BigDecimal("10000000")) > 0) {
            log.warn("[COMPLIANCE] Amount Rs.{} exceeds Rs.1 crore — requires manager approval", amount);
            return false;
        }
        return true;
    }
}
