package com.bank.loan.service;

import com.bank.loan.dto.*;
import com.bank.loan.model.LoanAccount;
import com.bank.loan.repository.LoanAccountRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class DisbursementServiceTest {

    @Mock LoanAccountRepository accountRepo;
    @Mock AuditService auditService;
    @Mock ComplianceService complianceService;
    @InjectMocks DisbursementService service;

    @Test
    void shouldDisburseSuccessfully() {
        when(complianceService.checkCompliance("SAV2001", new BigDecimal("500000"))).thenReturn(true);
        LoanAccount pool = mock(LoanAccount.class);
        LoanAccount borrower = mock(LoanAccount.class);
        when(accountRepo.findById("POOL-001")).thenReturn(Optional.of(pool));
        when(accountRepo.findById("SAV2001")).thenReturn(Optional.of(borrower));

        DisbursementResult result = service.disburse(
            new DisbursementRequest("SAV2001", new BigDecimal("500000"), "Home loan"));

        assertThat(result.status()).isEqualTo("DISBURSED");
        verify(pool).debit(new BigDecimal("500000"));
        verify(borrower).credit(new BigDecimal("500000"));
        verify(auditService).logDisbursement(eq("SAV2001"), any(), eq("SUCCESS"), anyString());
    }

    @Test
    void shouldAuditFailedDisbursement() {
        when(complianceService.checkCompliance("FRZ9001", new BigDecimal("500000"))).thenReturn(true);
        LoanAccount pool = mock(LoanAccount.class);
        LoanAccount frozen = mock(LoanAccount.class);
        doThrow(new IllegalStateException("FROZEN")).when(frozen).credit(any());
        when(accountRepo.findById("POOL-001")).thenReturn(Optional.of(pool));
        when(accountRepo.findById("FRZ9001")).thenReturn(Optional.of(frozen));

        assertThatThrownBy(() -> service.disburse(
            new DisbursementRequest("FRZ9001", new BigDecimal("500000"), null)))
            .isInstanceOf(IllegalStateException.class);

        // REQUIRES_NEW: audit committed even though main TX rolled back!
        verify(auditService).logDisbursement(eq("FRZ9001"), any(), eq("FAILED"), contains("FROZEN"));
    }
}
